/**
 * The index of an entry in `PEAKING_TABLE`.
 * @param table The frequency table (0-16, the EQ column is `value >> 3`).
 * @param q The Q index (0-4: 0.5, 1, 2, 4, 9).
 * @param gain The gain index (0-24: -12 to +12 dB).
 * @internal
 */
export function peakingEntry(table: number, q: number, gain: number) {
    return ((table * 5 + q) * 25 + gain) * 3;
}
